<?php $items=$invitations??[];$canInvite=!empty($residentContext['can_invite']);?>
<section class="resident-page-title"><span>Acceso temporal</span><h1>Mis visitas</h1><p>Crea invitaciones vinculadas a <?=e($residentContext['property_name']??'tu unidad')?>.</p></section>
<?php if($canInvite):?><button class="resident-primary-button" data-bs-toggle="modal" data-bs-target="#inviteModal"><i class="bi bi-person-plus"></i> Nueva invitación</button><?php endif;?>
<section class="resident-section"><div class="section-heading"><h2>Invitaciones</h2><span><?=count($items)?></span></div>
<?php foreach($items as $inv):$zk=(string)($inv['external_sync_status']??'not_requested');$zkBadge=match($zk){'synced'=>'success','pending'=>'warning','error'=>'danger','warning'=>'secondary',default=>'light'};?><article class="invitation-card"><div class="invitation-main"><span class="avatar-circle"><?=e(mb_strtoupper(mb_substr((string)$inv['visitor_name'],0,1)))?></span><div><strong><?=e($inv['visitor_name'])?></strong><span><?=e(format_datetime_es((string)$inv['starts_at']))?>–<?=e(date('H:i',strtotime((string)$inv['ends_at'])))?></span><?php if($inv['vehicle_plate']):?><small>Vehículo: <?=e($inv['vehicle_plate'])?></small><?php endif;?><small>ZKBio: <span class="badge text-bg-<?=$zkBadge?>"><?=e(match($zk){'synced'=>'registrado','pending'=>'enviando','warning'=>'requiere vínculo','error'=>'error',default=>'no solicitado'})?></span></small><?php if(!empty($inv['external_error'])):?><small class="text-danger"><?=e((string)$inv['external_error'])?></small><?php endif;?></div><span class="status-pill status-<?=e(status_badge((string)$inv['status']))?>"><?=e(status_label((string)$inv['status']))?></span></div><div class="invitation-code"><small>Código Property</small><strong><?=e($inv['access_code'])?></strong><button type="button" data-copy="<?=e($inv['access_code'])?>"><i class="bi bi-copy"></i> Copiar</button></div></article><?php endforeach;?>
<?php if(!$items):?><div class="resident-empty">No tienes invitaciones creadas.</div><?php endif;?></section>
<?php if($canInvite):?><div class="modal fade" id="inviteModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form class="modal-content resident-modal" method="post" action="<?=url('create-invitation')?>"><?=csrf_field()?><input type="hidden" name="return_route" value="resident-visitors"><div class="modal-header"><div><h5 class="modal-title">Nueva invitación</h5><small>Property intentará registrarla también en ZKBio cuando el anfitrión esté conciliado</small></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body resident-form"><label>Nombre del visitante<input name="name" required></label><div class="form-row"><label>Documento<input name="document"></label><label>Teléfono<input name="phone" inputmode="tel"></label></div><label>Fecha<input type="date" name="date" min="<?=date('Y-m-d')?>" required></label><div class="form-row"><label>Desde<input type="time" name="start" required></label><label>Hasta<input type="time" name="end" required></label></div><label>Vehículo opcional<input name="vehicle" placeholder="Placa"></label></div><div class="modal-footer"><button class="resident-secondary-button" type="button" data-bs-dismiss="modal">Cancelar</button><button class="resident-primary-button">Crear invitación</button></div></form></div></div><?php endif;?>
